def pair(name,A,B):
 ins=[A+B, A]
 print(name, [hex(ord(c)) for c in A+B], out(ins))
# skin tone after non emoji
for A in ["a","1"," ","💩","☝","🧑"]:
 pair(f"skin after {A!r}",A,"🏽")
