import subprocess, random
class Rep:
 def __init__(s,base,c): s.base=base; s.c=c
 def __repr__(s): return f"Rep({s.base},{s.c})"

def clusterize(tokens, min_rep=1, min_len=1):
    res=[]
    i=len(tokens)
    while i>0:
        found=None
        maxL=i//(min_rep+1)
        for L in range(min_len, maxL+1):
            block=tokens[i-L:i]
            R=1
            while i-(R+1)*L>=0 and tokens[i-(R+1)*L:i-R*L]==block:
                R+=1
            if R>=min_rep+1:
                found=(L,R,block); break
        if found:
            L,R,block=found
            base=clusterize(block, min_rep, min_len) if L>1 or isinstance(block[0],Rep) else block
            res.append(Rep(base,R)); i-=L*R
        else:
            res.append(tokens[i-1]); i-=1
    return list(reversed(res))
def render(clusters):
    out=""
    for c in clusters:
        if isinstance(c,Rep):
            inner=render(c.base)
            if len(c.base)==1 and not isinstance(c.base[0],Rep):
                out+=f"{inner}{{{c.c}}}"
            else:
                out+=f"(?:{inner}){{{c.c}}}"
        else:
            out+=c
    return out
def proto(s, min_rep=1, min_len=1):
    return "^"+render(clusterize(list(s),min_rep,min_len))+"$"
def ref(s, min_rep=1, min_len=1):
