import subprocess, random, itertools
# AST as tuples: ('empty',) ('tok',ch) ('class',frozenset) ('concat',tuple) ('union',tuple) ('opt',x)
EMPTY=('empty',)
def length(e):
    t=e[0]
    if t=='empty': return 0
    if t in ('tok','class'): return 1
    if t=='concat': return sum(length(x) for x in e[1])
    if t=='union': return max((length(x) for x in e[1]), default=0)
    if t=='opt': return length(e[1])
    raise ValueError(e)
def concat(*es):
    out=[]
    for e in es:
        if e[0]=='empty': continue
        if e[0]=='concat': out.extend(e[1])
        else: out.append(e)
    if not out: return EMPTY
    if len(out)==1: return out[0]
    return ('concat',tuple(out))
def make_union(terms):
    flat=[]
    for e in terms:
        if e[0]=='union': flat.extend(e[1])
        else: flat.append(e)
    # dedup preserve
    seen=set(); uniq=[]
    for e in flat:
        if e not in seen: seen.add(e); uniq.append(e)
    flat=uniq
    if EMPTY in flat:
        rest=[e for e in flat if e!=EMPTY]
        if not rest: return EMPTY
        inner=make_union(rest)
        return ('opt',inner)
    if not flat: return EMPTY
    if len(flat)==1: return flat[0]
    flat_sorted=sorted(flat, key=lambda e:-length(e)) # stable
    return ('union',tuple(flat_sorted))

def build(inputs):
    # trie nodes: dict token->node, final
    nodes=[] # [dict, final]
    def newnode():
        nodes.append([{},False]); return len(nodes)-1
    root=newnode()
    for s in sorted(set(inputs)):
        cur=root
        for ch in s:
            nxt=nodes[cur][0].get(ch)
            if nxt is None:
                nxt=newnode(); nodes[cur][0][ch]=nxt
            cur=nxt
        nodes[cur][1]=True
    # minimize by signature postorder (trie tree)
    canon={}; sig_to_id={}; min_nodes=[] # list of (final, dict token->cid in token sorted order)
    def canonical(u):
        if u in canon: return canon[u]
        child_map={}
        for tok,v in nodes[u][0].items(): child_map[tok]=canonical(v)
        sig=(nodes[u][1], tuple(sorted(child_map.items())))
        if sig in sig_to_id: cid=sig_to_id[sig]
        else:
            cid=len(min_nodes); sig_to_id[sig]=cid; min_nodes.append((nodes[u][1],child_map))
        canon[u]=cid; return cid
    croot=canonical(root)
    from functools import lru_cache
    # expression recursion with explicit memo and cycle check
    memo={}
    def expr(cid):
        if cid in memo: return memo[cid]
        memo[cid]=EMPTY # placeholder avoid cycles (shouldnt)
        final, trans = min_nodes[cid]
        # group by dest preserving trans order (child_map was original dict order from first node? in canonical code child_map follows nodes[u][0] order, which is insertion order)
        dests=[]
        bydest={}
        for tok,d in trans.items():
            if d not in bydest: bydest[d]=[]; dests.append(d)
            bydest[d].append(tok)
        terms=[]
        for d in dests:
            labels=bydest[d]
            de=expr(d)
            if len(labels)>1:
                lab=('class',frozenset(labels))
                terms.append(concat(lab,de))
            else:
                terms.append(concat(('tok',labels[0]),de))
        if final: terms.append(EMPTY)
        res=make_union(terms)
        memo[cid]=res; return res
