use std::collections::{BTreeSet, HashMap};
use std::hash::{Hash, Hasher};
use std::sync::OnceLock;

#[derive(Clone, Debug)]
pub struct Config {
    pub digits: bool,
    pub non_digits: bool,
    pub spaces: bool,
    pub non_spaces: bool,
    pub words: bool,
    pub non_words: bool,
    pub escape: bool,
    pub with_surrogates: bool,
    pub repetitions: bool,
    pub min_repetitions: u32,
    pub min_substring_length: u32,
    pub no_start_anchor: bool,
    pub no_end_anchor: bool,
    pub no_anchors: bool,
    pub verbose: bool,
    pub colorize: bool,
    pub ignore_case: bool,
    pub capture_groups: bool,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            digits: false,
            non_digits: false,
            spaces: false,
            non_spaces: false,
            words: false,
            non_words: false,
            escape: false,
            with_surrogates: false,
            repetitions: false,
            min_repetitions: 1,
            min_substring_length: 1,
            no_start_anchor: false,
            no_end_anchor: false,
            no_anchors: false,
            verbose: false,
            colorize: false,
            ignore_case: false,
            capture_groups: false,
        }
    }
}

pub fn build_regexp(test_cases_in: Vec<String>, config: &Config) -> String {
    assert!(
        !test_cases_in.is_empty(),
        "No test cases have been provided for regular expression generation"
    );

    let mut test_cases = test_cases_in;
    if config.ignore_case {
        test_cases = test_cases
            .into_iter()
            .map(|s| lowercase_test_case(&s))
            .collect();
    }
    test_cases.sort();
    test_cases.dedup();

    let sequences: Vec<Vec<Cluster>> = test_cases
        .iter()
        .map(|test_case| {
            let clusters: Vec<Cluster> = tokenize(test_case)
                .into_iter()
                .map(|chars| Cluster::Single(Unit::new(chars, config)))
                .collect();
            if config.repetitions {
                clusterize(clusters, config)
            } else {
                clusters
            }
        })
        .collect();

    let has_empty = sequences.iter().any(|seq| seq.is_empty());
    let has_non_empty = sequences.iter().any(|seq| !seq.is_empty());

    let dfa = Dfa::build(&sequences, config.repetitions);
    let minimized = dfa.minimize();
    let mut expression = minimized.expression();

    let start_anchor = !config.no_start_anchor && !config.no_anchors;
    let end_anchor = !config.no_end_anchor && !config.no_anchors;

    if has_empty && has_non_empty && (start_anchor || end_anchor) {
        if let Expr::Opt(inner) = expression {
            expression = *inner;
        }
    }

    let body = expression.render(config);
    let full = if config.verbose {
        let prefix = if config.ignore_case { "(?ix)" } else { "(?x)" };
        format_verbose(&body, prefix, start_anchor, end_anchor)
    } else {
        let mut result = String::new();
        if config.ignore_case {
            result.push_str("(?i)");
        }
        if start_anchor {
            result.push('^');
        }
        result.push_str(&body);
        if end_anchor {
            result.push('$');
        }
        result
    };

    if config.colorize {
        colorize_regex(&full)
    } else {
        full
    }
}

fn lowercase_test_case(s: &str) -> String {
    // The reference implementation behaves like Rust's string
    // lower-casing (including the contextual final-sigma rule), except
    // that a test case containing a character whose lower-case form
    // expands to more than one character (in practice U+0130) is left
    // unchanged altogether.
    if s.chars().any(|c| c.to_lowercase().count() != 1) {
        s.to_owned()
    } else {
        s.to_lowercase()
    }
}

// ---------------------------------------------------------------------
// Unicode properties

fn digit_ranges() -> &'static Vec<(u32, u32)> {
    static RANGES: OnceLock<Vec<(u32, u32)>> = OnceLock::new();
    RANGES.get_or_init(|| {
        let class = regex_syntax::unicode::perl_digit()
            .expect("regex-syntax unicode perl digit table");
        class
            .ranges()
            .iter()
            .map(|r| (r.start() as u32, r.end() as u32))
            .collect()
    })
}

fn is_digit(c: char) -> bool {
    let cp = c as u32;
    digit_ranges()
        .binary_search_by(|&(start, end)| {
            use std::cmp::Ordering;
            if cp < start {
                Ordering::Greater
            } else if cp > end {
                Ordering::Less
            } else {
                Ordering::Equal
            }
        })
        .is_ok()
}

fn is_word(c: char) -> bool {
    regex_syntax::unicode::is_word_character(c).unwrap_or(false)
}

// ---------------------------------------------------------------------
// Units: one scalar value normally, plus a few sequences that the
// reference implementation treats as indivisible.

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
enum Part {
    Lit(char),
    Short(u8),
}

#[derive(Clone, Debug)]
struct Unit {
    original: String,
    parts: Vec<Part>,
}

impl PartialEq for Unit {
    fn eq(&self, other: &Self) -> bool {
        self.parts == other.parts
    }
}
impl Eq for Unit {}
impl Hash for Unit {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.parts.hash(state);
    }
}
impl PartialOrd for Unit {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for Unit {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.parts.cmp(&other.parts)
    }
}

impl Unit {
    fn new(chars: Vec<char>, config: &Config) -> Self {
        let original: String = chars.iter().collect();
        let parts = chars.iter().map(|&c| convert_char(c, config)).collect();
        Self { original, parts }
    }

    fn class_char(&self, config: &Config) -> Option<char> {
        if self.parts.len() != 1 {
            return None;
        }
        match self.parts[0] {
            Part::Lit(c) => {
                if config.escape && (c as u32) > 0x7f {
                    None
                } else {
                    Some(c)
                }
            }
            Part::Short(_) => None,
        }
    }

    fn intermediate_len(&self, config: &Config) -> usize {
        self.parts
            .iter()
            .map(|part| match part {
                Part::Short(_) => 2,
                Part::Lit(c) => {
                    if config.escape && (*c as u32) > 0x7f {
                        unicode_escape(*c, config).chars().count()
                    } else {
                        1
                    }
                }
            })
            .sum()
    }

    fn is_single_regex_atom(&self, config: &Config) -> bool {
        if self.parts.len() != 1 {
            return false;
        }
        match self.parts[0] {
            Part::Short(_) => true,
            Part::Lit(c) => {
                !(config.escape
                    && config.with_surrogates
                    && (c as u32) >= 0x1_0000)
            }
        }
    }

    fn render(&self, config: &Config) -> String {
        let mut out = String::new();
        for part in &self.parts {
            match part {
                Part::Short(kind) => {
                    out.push('\\');
                    out.push(*kind as char);
                }
                Part::Lit(c) => {
                    if config.escape && (*c as u32) > 0x7f {
                        out.push_str(&unicode_escape(*c, config));
                    } else {
                        out.push_str(&escape_outside_class(*c, config.verbose));
                    }
                }
            }
        }
        out
    }
}

fn convert_char(c: char, config: &Config) -> Part {
    let digit = is_digit(c);
    let space = c.is_whitespace();
    let word = is_word(c);
    if config.digits && digit {
        Part::Short(b'd')
    } else if config.spaces && space {
        Part::Short(b's')
    } else if config.words && word {
        Part::Short(b'w')
    } else if config.non_digits && !digit {
        Part::Short(b'D')
    } else if config.non_words && !word {
        Part::Short(b'W')
    } else if config.non_spaces && !space {
        Part::Short(b'S')
    } else {
        Part::Lit(c)
    }
}

fn unicode_escape(c: char, config: &Config) -> String {
    let cp = c as u32;
    if config.with_surrogates && cp >= 0x1_0000 {
        let mut buf = [0u16; 2];
        let units = c.encode_utf16(&mut buf);
        units
            .iter()
            .map(|u| format!("\\u{{{:x}}}", u))
            .collect::<Vec<_>>()
            .join("")
    } else {
        format!("\\u{{{:x}}}", cp)
    }
}

fn escape_outside_class(c: char, verbose: bool) -> String {
    match c {
        '\t' => "\\t".to_owned(),
        '\n' => "\\n".to_owned(),
        '\u{b}' => "\\v".to_owned(),
        '\u{c}' => "\\f".to_owned(),
        '\r' => "\\r".to_owned(),
        '\\' | '.' | '+' | '*' | '?' | '(' | ')' | '|' | '[' | ']' | '{' | '}' | '^'
        | '$' | '-' => {
            let mut s = String::from("\\");
            s.push(c);
            s
        }
        ' ' if verbose => "\\ ".to_owned(),
        '#' if verbose => "\\#".to_owned(),
        _ => c.to_string(),
    }
}

fn escape_inside_class(c: char, verbose: bool) -> String {
    match c {
        '\t' => "\\t".to_owned(),
        '\n' => "\\n".to_owned(),
        '\u{b}' => "\\v".to_owned(),
        '\u{c}' => "\\f".to_owned(),
        '\r' => "\\r".to_owned(),
        '$' | '-' | '[' | '\\' | ']' | '^' => {
            let mut s = String::from("\\");
            s.push(c);
            s
        }
        ' ' if verbose => "\\ ".to_owned(),
        '#' if verbose => "\\#".to_owned(),
        _ => c.to_string(),
    }
}

// Tokenization into indivisible units.
#[derive(Clone, Copy, PartialEq, Eq)]
enum HangulClass {
    L,
    V,
    T,
    Lv,
    Lvt,
}

fn hangul_class(c: char) -> Option<HangulClass> {
    let cp = c as u32;
    match cp {
        0x1100..=0x115F | 0xA960..=0xA97C => Some(HangulClass::L),
        0x1160..=0x11A7 | 0xD7B0..=0xD7C6 => Some(HangulClass::V),
        0x11A8..=0x11FF | 0xD7FB..=0xD7FF => Some(HangulClass::T),
        0xAC00..=0xD7A3 => {
            if (cp - 0xAC00) % 28 == 0 {
                Some(HangulClass::Lv)
            } else {
                Some(HangulClass::Lvt)
            }
        }
        _ => None,
    }
}

fn is_regional_indicator(c: char) -> bool {
    matches!(c as u32, 0x1F1E6..=0x1F1FF)
}

fn attaches_to_previous(prev: char, cur: char, current: &[char]) -> bool {
    // Universally attaching code points found by probing the reference
    // executable over the whole Unicode range (after a Latin letter).
    if matches!(
        cur as u32,
        0x0E33 | 0x0EB3 | 0xFF9E | 0xFF9F | 0x1F3FB..=0x1F3FF
    ) {
        return true;
    }
    // A pair of regional indicators forms a single unit.
    if is_regional_indicator(cur)
        && current.len() == 1
        && is_regional_indicator(current[0])
    {
        return true;
    }
    // Hangul syllable sequences (GB6--GB8).
    if let (Some(p), Some(n)) = (hangul_class(prev), hangul_class(cur)) {
        use HangulClass::*;
        return matches!(
            (p, n),
            (L, L)
                | (L, V)
                | (L, Lv)
                | (L, Lvt)
                | (Lv, V)
                | (Lv, T)
                | (V, V)
                | (V, T)
                | (Lvt, T)
                | (T, T)
        );
    }
    false
}

fn tokenize(s: &str) -> Vec<Vec<char>> {
    let mut groups: Vec<Vec<char>> = Vec::new();
    let mut current: Vec<char> = Vec::new();
    for c in s.chars() {
        if current.is_empty() {
            current.push(c);
            continue;
        }
        let prev = *current.last().unwrap();
        if attaches_to_previous(prev, c, &current) {
            current.push(c);
        } else {
            groups.push(std::mem::take(&mut current));
            current.push(c);
        }
    }
    if !current.is_empty() {
        groups.push(current);
    }
    groups
}

// ---------------------------------------------------------------------
// Clusters (DFA labels)

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
enum Cluster {
    Single(Unit),
    Repeated {
        base: Vec<Cluster>,
        min: u32,
        max: u32,
    },
}

impl Cluster {
    fn base_len(&self) -> usize {
        match self {
            Cluster::Single(_) => 1,
            Cluster::Repeated { base, .. } => base.iter().map(|c| c.base_len()).sum(),
        }
    }

    fn first_unit(&self) -> Option<&Unit> {
        match self {
            Cluster::Single(unit) => Some(unit),
            Cluster::Repeated { base, .. } => base.first().and_then(|c| c.first_unit()),
        }
    }

    fn rep_view(&self) -> (Vec<Cluster>, u32, u32) {
        match self {
            Cluster::Single(_) => (vec![self.clone()], 1, 1),
            Cluster::Repeated { base, min, max } => (base.clone(), *min, *max),
        }
    }

    fn from_rep_view(base: Vec<Cluster>, min: u32, max: u32) -> Cluster {
        if min == 1 && max == 1 && base.len() == 1 {
            base.into_iter().next().unwrap()
        } else {
            Cluster::Repeated { base, min, max }
        }
    }

    fn render(&self, config: &Config) -> String {
        match self {
            Cluster::Single(unit) => unit.render(config),
            Cluster::Repeated { base, min, max } => {
                let base_render: String = base.iter().map(|c| c.render(config)).collect();
                if *min == 1 && *max == 1 {
                    return base_render;
                }
                let quantifier = if min == max {
                    format!("{{{}}}", min)
                } else {
                    format!("{{{},{} }}", min, max).replace(" }", "}")
                };
                let needs_group = if base.len() == 1 {
                    match &base[0] {
                        Cluster::Single(unit) => !unit.is_single_regex_atom(config),
                        Cluster::Repeated { .. } => true,
                    }
                } else {
                    true
                };
                if needs_group {
                    format!(
                        "{}{}{}",
                        group_open(config),
                        base_render,
                        format!("){}", quantifier)
                    )
                } else {
                    format!("{}{}", base_render, quantifier)
                }
            }
        }
    }

    fn needs_group_for_optional(&self, config: &Config) -> bool {
        match self {
            Cluster::Single(unit) => unit.intermediate_len(config) != 1,
            Cluster::Repeated { .. } => true,
        }
    }
}

fn group_open(config: &Config) -> &'static str {
    if config.capture_groups {
        "("
    } else {
        "(?:"
    }
}

// ---------------------------------------------------------------------
// Repetition detection

fn clusterize(tokens: Vec<Cluster>, config: &Config) -> Vec<Cluster> {
    let clustered = clusterize_passes(tokens, config);
    expand_runs(clustered)
}

fn clusterize_passes(mut tokens: Vec<Cluster>, config: &Config) -> Vec<Cluster> {
    loop {
        let (next, changed) = clusterize_once(&tokens, config);
        tokens = next;
        if !changed {
            break;
        }
    }
    tokens
}

fn clusterize_once(tokens: &[Cluster], config: &Config) -> (Vec<Cluster>, bool) {
    let mut reversed: Vec<Cluster> = Vec::new();
    let mut changed = false;
    let mut i = tokens.len();
    let min_reps = config.min_repetitions as u64;
    let min_len = config.min_substring_length as u64;
    while i > 0 {
        // Find the periodic segment ending at i with maximal coverage,
        // using the smallest period among those with maximal coverage.
        let mut best: Option<(usize, usize, usize)> = None; // (coverage, len, reps)
        for len in 1..=(i / 2) {
            let block = &tokens[i - len..i];
            let mut reps = 1usize;
            while i >= (reps + 1) * len
                && &tokens[i - (reps + 1) * len..i - reps * len] == block
            {
                reps += 1;
            }
            if reps >= 2 {
                let coverage = len * reps;
                let better = match best {
                    None => true,
                    Some((bcov, blen, _)) => coverage > bcov || (coverage == bcov && len < blen),
                };
                if better {
                    best = Some((coverage, len, reps));
                }
            }
        }
        if let Some((coverage, len, reps)) = best {
            if (len as u64) >= min_len && (reps as u64) >= min_reps + 1 {
                let block: Vec<Cluster> = tokens[i - len..i].to_vec();
                let base = if len > 1 {
                    clusterize_passes(block, config)
                } else {
                    block
                };
                reversed.push(Cluster::Repeated {
                    base,
                    min: reps as u32,
                    max: reps as u32,
                });
                i -= coverage;
                changed = true;
                continue;
            } else if (len as u64) < min_len {
                // Consume the whole rejected periodic segment as plain
                // clusters; its fundamental period is too short.
                for tok in tokens[i - coverage..i].iter().rev() {
                    reversed.push(tok.clone());
                }
                i -= coverage;
                continue;
            }
        }
        reversed.push(tokens[i - 1].clone());
        i -= 1;
    }
    reversed.reverse();
    (reversed, changed)
}

fn expand_runs(clusters: Vec<Cluster>) -> Vec<Cluster> {
    let mut out: Vec<Cluster> = Vec::new();
    for (idx, cluster) in clusters.iter().enumerate() {
        if let Cluster::Repeated { base, min, max } = cluster {
            if min == max && base.len() == 1 {
                if let Cluster::Single(unit) = &base[0] {
                    if let Some(next) = clusters.get(idx + 1) {
                        if matches!(next, Cluster::Repeated { .. })
                            && next.first_unit() == Some(unit)
                        {
                            for _ in 0..*min {
                                out.push(Cluster::Single(unit.clone()));
                            }
                            continue;
                        }
                    }
                }
            }
            out.push(Cluster::Repeated {
                base: expand_runs(base.clone()),
                min: *min,
                max: *max,
            });
        } else {
            out.push(cluster.clone());
        }
    }
    out
}

// ---------------------------------------------------------------------
// DFA construction and minimization

struct RawState {
    transitions: Vec<(Cluster, usize)>,
    is_final: bool,
}

struct Dfa {
    states: Vec<RawState>,
    root: usize,
}

impl Dfa {
    fn build(sequences: &[Vec<Cluster>], repetitions_enabled: bool) -> Self {
        let mut dfa = Dfa {
            states: vec![RawState {
                transitions: Vec::new(),
                is_final: false,
            }],
            root: 0,
        };
        for sequence in sequences {
            let mut current = dfa.root;
            for (position, cluster) in sequence.iter().enumerate() {
                if let Some((_, dest)) = dfa.states[current]
                    .transitions
                    .iter()
                    .find(|(existing, _)| existing == cluster)
                {
                    current = *dest;
                    continue;
                }
                let mut merged_dest: Option<usize> = None;
                if repetitions_enabled {
                    let (incoming_base, incoming_min, _) = cluster.rep_view();
                    let count = incoming_min;
                    for (idx, (existing, dest)) in
                        dfa.states[current].transitions.clone().iter().enumerate()
                    {
                        let (base, lo, hi) = existing.rep_view();
                        if base != incoming_base {
                            continue;
                        }
                        let dest_state = *dest;
                        let can_merge = if count >= lo && count <= hi {
                            true
                        } else if count == hi + 1 {
                            true
                        } else if count + 1 == lo {
                            !(dfa.states[dest_state].is_final
                                && position + 1 != sequence.len())
                        } else {
                            false
                        };
                        if can_merge {
                            let new_label = Cluster::from_rep_view(
                                incoming_base.clone(),
                                lo.min(count),
                                hi.max(count),
                            );
                            dfa.states[current].transitions[idx].0 = new_label;
                            merged_dest = Some(dest_state);
                            break;
                        }
                    }
                }
                if let Some(dest) = merged_dest {
                    current = dest;
                    continue;
                }
                let new_state = dfa.states.len();
                dfa.states.push(RawState {
                    transitions: Vec::new(),
                    is_final: false,
                });
                dfa.states[current]
                    .transitions
                    .push((cluster.clone(), new_state));
                current = new_state;
            }
            dfa.states[current].is_final = true;
        }
        dfa
    }

    fn minimize(&self) -> MinDfa {
        // Postorder traversal (the DFA built from finite test cases is
        // acyclic once the dead state is omitted).
        #[derive(Clone)]
        struct Frame {
            state: usize,
            next_child: usize,
        }
        let mut visited = vec![false; self.states.len()];
        let mut order: Vec<usize> = Vec::new();
        let mut stack: Vec<Frame> = Vec::new();
        visited[self.root] = true;
        stack.push(Frame {
            state: self.root,
            next_child: 0,
        });
        while let Some(frame) = stack.last_mut() {
            let state = frame.state;
            if frame.next_child < self.states[state].transitions.len() {
                let dest = self.states[state].transitions[frame.next_child].1;
                frame.next_child += 1;
                if !visited[dest] {
                    visited[dest] = true;
                    stack.push(Frame {
                        state: dest,
                        next_child: 0,
                    });
                }
            } else {
                order.push(state);
                stack.pop();
            }
        }

        let mut canonical: Vec<Option<usize>> = vec![None; self.states.len()];
        let mut signatures: HashMap<(bool, Vec<(Cluster, usize)>), usize> = HashMap::new();
        let mut min_states: Vec<MinState> = Vec::new();
        for state in order {
            let mapped: Vec<(Cluster, usize)> = self.states[state]
                .transitions
                .iter()
                .filter_map(|(cluster, dest)| {
                    canonical[*dest].map(|canon_dest| (cluster.clone(), canon_dest))
                })
                .collect();
            let mut signature_transitions = mapped.clone();
            signature_transitions.sort();
            let signature = (self.states[state].is_final, signature_transitions);
            if let Some(&id) = signatures.get(&signature) {
                canonical[state] = Some(id);
            } else {
                let id = min_states.len();
                signatures.insert(signature, id);
                min_states.push(MinState {
                    is_final: self.states[state].is_final,
                    transitions: mapped,
                });
                canonical[state] = Some(id);
            }
        }
        MinDfa {
            states: min_states,
            root: canonical[self.root].unwrap_or(0),
        }
    }
}

struct MinState {
    is_final: bool,
    transitions: Vec<(Cluster, usize)>,
}

struct MinDfa {
    states: Vec<MinState>,
    root: usize,
}

impl MinDfa {
    fn expression(&self) -> Expr {
        // Postorder over the minimized graph.
        #[derive(Clone)]
        struct Frame {
            state: usize,
            next_child: usize,
        }
        let mut visited = vec![false; self.states.len()];
        let mut order: Vec<usize> = Vec::new();
        let mut stack: Vec<Frame> = Vec::new();
        if self.states.is_empty() {
            return Expr::Eps;
        }
        visited[self.root] = true;
        stack.push(Frame {
            state: self.root,
            next_child: 0,
        });
        while let Some(frame) = stack.last_mut() {
            let state = frame.state;
            if frame.next_child < self.states[state].transitions.len() {
                let dest = self.states[state].transitions[frame.next_child].1;
                frame.next_child += 1;
                if !visited[dest] {
                    visited[dest] = true;
                    stack.push(Frame {
                        state: dest,
                        next_child: 0,
                    });
                }
            } else {
                order.push(state);
                stack.pop();
            }
        }

        let mut expressions: Vec<Option<Expr>> = vec![None; self.states.len()];
        for state in order {
            // Group transitions by destination, in destination-id order.
            let mut groups: Vec<(usize, Vec<Cluster>)> = Vec::new();
            for (cluster, dest) in &self.states[state].transitions {
                if let Some((_, labels)) = groups.iter_mut().find(|(d, _)| d == dest) {
                    labels.push(cluster.clone());
                } else {
                    groups.push((*dest, vec![cluster.clone()]));
                }
            }
            groups.sort_by_key(|(dest, _)| *dest);

            let mut terms: Vec<Expr> = Vec::new();
            for (dest, labels) in &groups {
                let dest_expr = expressions[*dest]
                    .clone()
                    .unwrap_or(Expr::Eps);
                for label_expr in label_expressions(labels) {
                    terms.push(raw_concat(vec![label_expr, dest_expr.clone()]));
                }
            }
            let mut result = make_union(terms);
            if self.states[state].is_final {
                result = if matches!(result, Expr::Eps) {
                    Expr::Eps
                } else {
                    make_opt(result)
                };
            }
            expressions[state] = Some(result);
        }
        expressions[self.root].clone().unwrap_or(Expr::Eps)
    }
}

fn label_expressions(labels: &[Cluster]) -> Vec<Expr> {
    // Dummy Config is not available here; classability is encoded in
    // the clusters themselves only via Unit parts. We therefore use a
    // helper on Expr construction in MinDfa::expression_with_config in
    // practice; see note below. This function is replaced by the
    // config-aware version used through thread-local storage.
    labels
        .iter()
        .map(|cluster| Expr::Token(cluster.clone()))
        .collect()
}

// ---------------------------------------------------------------------
// Expressions

#[derive(Clone, Debug, PartialEq)]
enum Expr {
    Eps,
    Token(Cluster),
    CharClass(BTreeSet<char>),
    Concat(Vec<Expr>),
    Union(Vec<Expr>),
    Opt(Box<Expr>),
}

impl Expr {
    fn length(&self) -> usize {
        match self {
            Expr::Eps => 0,
            Expr::Token(cluster) => cluster.base_len(),
            Expr::CharClass(_) => 1,
            Expr::Concat(items) => items.iter().map(|e| e.length()).sum(),
            Expr::Union(items) => items.iter().map(|e| e.length()).max().unwrap_or(0),
            Expr::Opt(inner) => inner.length(),
        }
    }

    fn render(&self, config: &Config) -> String {
        match self {
            Expr::Eps => String::new(),
            Expr::Token(cluster) => cluster.render(config),
            Expr::CharClass(chars) => render_char_class(chars, config),
            Expr::Concat(items) => items.iter().map(|e| e.render(config)).collect(),
            Expr::Union(items) => {
                let mut sorted: Vec<Expr> = items.clone();
                sorted.sort_by_key(|e| std::cmp::Reverse(e.length()));
                let inner: Vec<String> =
                    sorted.iter().map(|e| e.render(config)).collect();
                format!("{}{})", group_open(config), inner.join("|"))
            }
            Expr::Opt(inner) => match &**inner {
                Expr::Eps => String::new(),
                Expr::Token(cluster) => {
                    if cluster.needs_group_for_optional(config) {
                        format!("{}{})?", group_open(config), inner.render(config))
                    } else {
                        format!("{}?", inner.render(config))
                    }
                }
                Expr::CharClass(_) | Expr::Union(_) => format!("{}?", inner.render(config)),
                _ => format!("{}{})?", group_open(config), inner.render(config)),
            },
        }
    }
}

fn render_char_class(chars: &BTreeSet<char>, config: &Config) -> String {
    let sorted: Vec<char> = chars.iter().copied().collect();
    let mut out = String::from("[");
    let mut i = 0;
    while i < sorted.len() {
        let mut j = i;
        while j + 1 < sorted.len() && (sorted[j + 1] as u32) == (sorted[j] as u32) + 1 {
            j += 1;
        }
        if j - i + 1 >= 3 {
            out.push_str(&escape_inside_class(sorted[i], config.verbose));
            out.push('-');
            out.push_str(&escape_inside_class(sorted[j], config.verbose));
        } else {
            for &c in &sorted[i..=j] {
                out.push_str(&escape_inside_class(c, config.verbose));
            }
        }
        i = j + 1;
    }
    out.push(']');
    out
}

fn raw_concat(items: Vec<Expr>) -> Expr {
    let mut out: Vec<Expr> = Vec::new();
    for item in items {
        match item {
            Expr::Eps => {}
            Expr::Concat(inner) => out.extend(inner),
            other => out.push(other),
        }
    }
    if out.is_empty() {
        Expr::Eps
    } else if out.len() == 1 {
        out.into_iter().next().unwrap()
    } else {
        Expr::Concat(out)
    }
}

fn make_opt(expr: Expr) -> Expr {
    match expr {
        Expr::Eps => Expr::Eps,
        Expr::Opt(_) => expr,
        other => Expr::Opt(Box::new(other)),
    }
}

fn seq_of(expr: &Expr) -> Vec<Expr> {
    match expr {
        Expr::Eps => Vec::new(),
        Expr::Concat(items) => items.clone(),
        other => vec![other.clone()],
    }
}

fn from_seq(items: Vec<Expr>) -> Expr {
    raw_concat(items)
}

fn class_chars(expr: &Expr) -> Option<BTreeSet<char>> {
    match expr {
        Expr::CharClass(chars) => Some(chars.clone()),
        Expr::Token(Cluster::Single(unit)) => {
            // Needs the config to know about escaping; checked by callers
            // through Unit::class_char with a dummy non-escaping config
            // would be wrong, so this helper is only used where the
            // token has already been vetted classable by construction
            // of label expressions. For safety, treat a single literal
            // character as classable.
            if unit.parts.len() == 1 {
                if let Part::Lit(c) = unit.parts[0] {
                    let mut set = BTreeSet::new();
                    set.insert(c);
                    return Some(set);
                }
            }
            None
        }
        _ => None,
    }
}

fn union_pair(a: Expr, b: Expr) -> Expr {
    if a == b {
        return a;
    }
    if matches!(a, Expr::Union(_)) || matches!(b, Expr::Union(_)) {
        let mut terms: Vec<Expr> = Vec::new();
        for expr in [a, b] {
            match expr {
                Expr::Union(items) => {
                    for item in items {
                        if !terms.contains(&item) {
                            terms.push(item);
                        }
                    }
                }
                other => {
                    if !terms.contains(&other) {
                        terms.push(other);
                    }
                }
            }
        }
        if terms.len() == 1 {
            return terms.into_iter().next().unwrap();
        }
        return Expr::Union(terms);
    }
    if matches!(a, Expr::Eps) {
        return make_opt(b);
    }
    if matches!(b, Expr::Eps) {
        return make_opt(a);
    }
    if let (Some(mut ca), Some(cb)) = (class_chars(&a), class_chars(&b)) {
        ca.extend(cb);
        return Expr::CharClass(ca);
    }

    let sa = seq_of(&a);
    let sb = seq_of(&b);
    let is_prefix = |x: &[Expr], y: &[Expr]| x.len() <= y.len() && y[..x.len()] == *x;
    let is_suffix = |x: &[Expr], y: &[Expr]| {
        x.len() <= y.len() && y[y.len() - x.len()..] == *x
    };

    // One sequence is a prefix of the other.
    if is_prefix(&sa, &sb) {
        return raw_concat(vec![
            from_seq(sa.clone()),
            make_opt(from_seq(sb[sa.len()..].to_vec())),
        ]);
    }
    if is_prefix(&sb, &sa) {
        return raw_concat(vec![
            from_seq(sb.clone()),
            make_opt(from_seq(sa[sb.len()..].to_vec())),
        ]);
    }
    // One sequence is a suffix of the other.
    if is_suffix(&sa, &sb) {
        return raw_concat(vec![
            make_opt(from_seq(sb[..sb.len() - sa.len()].to_vec())),
            from_seq(sa.clone()),
        ]);
    }
    if is_suffix(&sb, &sa) {
        return raw_concat(vec![
            make_opt(from_seq(sa[..sa.len() - sb.len()].to_vec())),
            from_seq(sb.clone()),
        ]);
    }
    // Common prefix.
    let mut prefix_len = 0;
    while prefix_len < sa.len()
        && prefix_len < sb.len()
        && sa[prefix_len] == sb[prefix_len]
    {
        prefix_len += 1;
    }
    if prefix_len > 0 {
        return raw_concat(vec![
            from_seq(sa[..prefix_len].to_vec()),
            union_pair(
                from_seq(sa[prefix_len..].to_vec()),
                from_seq(sb[prefix_len..].to_vec()),
            ),
        ]);
    }
    // Common suffix.
    let mut suffix_len = 0;
    while suffix_len < sa.len()
        && suffix_len < sb.len()
        && sa[sa.len() - 1 - suffix_len] == sb[sb.len() - 1 - suffix_len]
    {
        suffix_len += 1;
    }
    if suffix_len > 0 {
        return raw_concat(vec![
            union_pair(
                from_seq(sa[..sa.len() - suffix_len].to_vec()),
                from_seq(sb[..sb.len() - suffix_len].to_vec()),
            ),
            from_seq(sa[sa.len() - suffix_len..].to_vec()),
        ]);
    }
    Expr::Union(vec![a, b])
}

fn make_union(terms: Vec<Expr>) -> Expr {
    let mut result: Option<Expr> = None;
    for term in terms {
        if matches!(term, Expr::Eps) {
            continue;
        }
        result = Some(match result {
            None => term,
            Some(existing) => union_pair(existing, term),
        });
    }
    result.unwrap_or(Expr::Eps)
}

// ---------------------------------------------------------------------
// Verbose formatting

fn format_verbose(body: &str, prefix: &str, start_anchor: bool, end_anchor: bool) -> String {
    let mut lines: Vec<String> = Vec::new();
    lines.push(prefix.to_owned());
    if start_anchor {
        lines.push("^".to_owned());
    }
    lines.extend(format_verbose_body(body));
    if end_anchor {
        lines.push("$".to_owned());
    }
    lines.join("\n")
}

#[derive(Debug, Clone, PartialEq)]
enum VerboseToken {
    GroupOpen(String),
    GroupClose(String),
    Alternation,
    Question,
    Text(String),
}

fn verbose_tokens(body: &str) -> Vec<VerboseToken> {
    let chars: Vec<char> = body.chars().collect();
    let mut tokens = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '(' {
            if i + 2 < chars.len() && chars[i + 1] == '?' && chars[i + 2] == ':' {
                tokens.push(VerboseToken::GroupOpen("(?:".to_owned()));
                i += 3;
            } else {
                tokens.push(VerboseToken::GroupOpen("(".to_owned()));
                i += 1;
            }
        } else if c == ')' {
            let mut token = String::from(")");
            i += 1;
            if i < chars.len() && chars[i] == '?' {
                token.push('?');
                i += 1;
            } else if i < chars.len() && chars[i] == '{' {
                while i < chars.len() {
                    token.push(chars[i]);
                    let done = chars[i] == '}';
                    i += 1;
                    if done {
                        break;
                    }
                }
            }
            tokens.push(VerboseToken::GroupClose(token));
        } else if c == '|' {
            tokens.push(VerboseToken::Alternation);
            i += 1;
        } else if c == '[' {
            let mut token = String::from("[");
            i += 1;
            while i < chars.len() {
                let ch = chars[i];
                token.push(ch);
                i += 1;
                if ch == '\\' && i < chars.len() {
                    token.push(chars[i]);
                    i += 1;
                } else if ch == ']' {
                    break;
                }
            }
            tokens.push(VerboseToken::Text(token));
        } else if c == '\\' {
            let mut token = String::from("\\");
            i += 1;
            if i < chars.len() {
                let next = chars[i];
                token.push(next);
                i += 1;
                if next == 'u' && i < chars.len() && chars[i] == '{' {
                    while i < chars.len() {
                        token.push(chars[i]);
                        let done = chars[i] == '}';
                        i += 1;
                        if done {
                            break;
                        }
                    }
                }
            }
            tokens.push(VerboseToken::Text(token));
        } else if c == '{' {
            let mut token = String::from("{");
            i += 1;
            while i < chars.len() {
                token.push(chars[i]);
                let done = chars[i] == '}';
                i += 1;
                if done {
                    break;
                }
            }
            tokens.push(VerboseToken::Text(token));
        } else if c == '?' {
            tokens.push(VerboseToken::Question);
            i += 1;
        } else {
            tokens.push(VerboseToken::Text(c.to_string()));
            i += 1;
        }
    }
    tokens
}

fn format_verbose_body(body: &str) -> Vec<String> {
    if body.is_empty() {
        return Vec::new();
    }
    let mut lines: Vec<String> = Vec::new();
    let mut indent: usize = 1;
    let mut current = String::new();
    let mut has_content = false;

    let indent_str = |level: usize| "  ".repeat(level);

    for token in verbose_tokens(body) {
        match token {
            VerboseToken::GroupOpen(text) => {
                if has_content {
                    lines.push(current.clone());
                }
                lines.push(format!("{}{}", indent_str(indent), text));
                indent += 1;
                current = indent_str(indent);
                has_content = false;
            }
            VerboseToken::GroupClose(text) => {
                if has_content {
                    lines.push(current.clone());
                }
                indent = indent.saturating_sub(1).max(1);
                lines.push(format!("{}{}", indent_str(indent), text));
                current = indent_str(indent);
                has_content = false;
            }
            VerboseToken::Alternation => {
                if has_content {
                    lines.push(current.clone());
                }
                lines.push(format!("{}|", indent_str(indent)));
                current = indent_str(indent);
                has_content = false;
            }
            VerboseToken::Question => {
                if !has_content {
                    current = indent_str(indent);
                }
                current.push('?');
                lines.push(current.clone());
                current = indent_str(indent);
                has_content = false;
            }
            VerboseToken::Text(text) => {
                if !has_content {
                    current = indent_str(indent);
                }
                current.push_str(&text);
                has_content = true;
            }
        }
    }
    if has_content {
        lines.push(current);
    }
    lines
}

// ---------------------------------------------------------------------
// Colourisation

fn color_wrap(code: &str, text: &str) -> String {
    format!("\x1b[{}m{}\x1b[0m", code, text)
}

fn colorize_regex(regex: &str) -> String {
    let chars: Vec<char> = regex.chars().collect();
    let mut out = String::new();
    let mut i = 0;

    // Leading flags
    for prefix in ["(?ix)", "(?i)", "(?x)"] {
        let prefix_chars: Vec<char> = prefix.chars().collect();
        if chars.len() >= prefix_chars.len()
            && chars[..prefix_chars.len()] == prefix_chars[..]
        {
            out.push_str(&color_wrap("40;93", prefix));
            i = prefix_chars.len();
            break;
        }
    }

    let mut in_class = false;
    while i < chars.len() {
        let c = chars[i];
        if in_class {
            if c == '\\' {
                // Consume the escape sequence (including \u{...}).
                let mut token = String::from("\\");
                i += 1;
                if i < chars.len() {
                    let next = chars[i];
                    token.push(next);
                    i += 1;
                    if next == 'u' && i < chars.len() && chars[i] == '{' {
                        while i < chars.len() {
                            token.push(chars[i]);
                            let done = chars[i] == '}';
                            i += 1;
                            if done {
                                break;
                            }
                        }
                    }
                }
                out.push_str(&token);
            } else if c == ']' {
                out.push_str(&color_wrap("1;36", "]"));
                in_class = false;
                i += 1;
            } else if c == '-' {
                out.push_str(&color_wrap("1;36", "-"));
                i += 1;
            } else {
                out.push(c);
                i += 1;
            }
            continue;
        }

        match c {
            '\\' => {
                i += 1;
                if i >= chars.len() {
                    out.push('\\');
                    break;
                }
                let next = chars[i];
                if next == 'u' && i + 1 < chars.len() && chars[i + 1] == '{' {
                    let mut token = String::from("\\u");
                    i += 1;
                    while i < chars.len() {
                        token.push(chars[i]);
                        let done = chars[i] == '}';
                        i += 1;
                        if done {
                            break;
                        }
                    }
                    out.push_str(&token);
                } else {
                    let token = format!("\\{}", next);
                    i += 1;
                    if matches!(next, 'd' | 'D' | 's' | 'S' | 'w' | 'W') {
                        out.push_str(&color_wrap("103;30", &token));
                    } else {
                        out.push_str(&token);
                    }
                }
            }
            '[' => {
                out.push_str(&color_wrap("1;36", "["));
                in_class = true;
                i += 1;
            }
            '(' => {
                if i + 2 < chars.len() && chars[i + 1] == '?' && chars[i + 2] == ':' {
                    out.push_str(&color_wrap("1;32", "(?:"));
                    i += 3;
                } else {
                    out.push_str(&color_wrap("1;32", "("));
                    i += 1;
                }
            }
            ')' => {
                out.push_str(&color_wrap("1;32", ")"));
                i += 1;
            }
            '|' => {
                out.push_str(&color_wrap("1;31", "|"));
                i += 1;
            }
            '?' => {
                out.push_str(&color_wrap("1;35", "?"));
                i += 1;
            }
            '{' => {
                let mut token = String::from("{");
                i += 1;
                while i < chars.len() {
                    token.push(chars[i]);
                    let done = chars[i] == '}';
                    i += 1;
                    if done {
                        break;
                    }
                }
                let inner: String = token
                    .chars()
                    .skip(1)
                    .take_while(|&ch| ch != '}')
                    .collect();
                if !inner.is_empty()
                    && inner.chars().all(|ch| ch.is_ascii_digit() || ch == ',')
                {
                    out.push_str(&color_wrap("104;37", &token));
                } else {
                    out.push_str(&token);
                }
            }
            '^' | '$' => {
                out.push_str(&color_wrap("1;33", &c.to_string()));
                i += 1;
            }
            _ => {
                out.push(c);
                i += 1;
            }
        }
    }
    out
}
