{"command":"mkdir -p vendor/terminal_size/src
cat > vendor/terminal_size/Cargo.toml << 'EOF'
[package]
name = "terminal_size"
version = "0.4.3"
edition = "2021"
license = "MIT OR Apache-2.0"
description = "Minimal terminal size detection used by this project's clap configuration"

[dependencies]
libc = "0.2"
EOF
cat > vendor/terminal_size/src/lib.rs << 'RS'
//! Minimal terminal-size detection for Unix terminals.
//!
//! This implementation is intentionally small: it reports the size of
//! the first of stdout, stderr or stdin that is attached to a terminal.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Width(pub u16);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Height(pub u16);

fn terminal_size_using_fd(fd: libc::c_int) -> Option<(Width, Height)> {
    unsafe {
        let mut winsize: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsize) != 0 {
            return None;
        }
        if winsize.ws_col == 0 {
            return None;
        }
        Some((Width(winsize.ws_col), Height(winsize.ws_row)))
    }
}

pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_using_fd(libc::STDOUT_FILENO)
        .or_else(|| terminal_size_using_fd(libc::STDERR_FILENO))
        .or_else(|| terminal_size_using_fd(libc::STDIN_FILENO))
}
RS
