old3="""            Expr::Union(items) => {
                let mut sorted: Vec<Expr> = items.clone();"""
new3="""            Expr::Union(items) if items.contains(&Expr::Eps) => {
                let rest: Vec<Expr> = items
                    .iter()
                    .filter(|item| !matches!(item, Expr::Eps))
                    .cloned()
                    .collect();
                if rest.is_empty() {
                    return String::new();
                }
                let inner = if rest.len() == 1 {
                    rest[0].clone()
                } else {
                    Expr::Union(rest)
                };
                return Expr::Opt(Box::new(inner)).render(config);
            }
            Expr::Union(items) => {
                let mut sorted: Vec<Expr> = items.clone();"""
assert old3 in s;s=s.replace(old3,new3)
open('src/builder.rs','w').write(s)
