// Validation of an unanchored regular expression.
//
// When both anchors are removed, the reference implementation parses
// the resulting pattern with the `regex` crate before displaying it.
// Patterns containing surrogate-pair escapes (which are not valid
// Unicode scalar values) therefore cause it to panic. This module
// deliberately reproduces that observable behaviour; the layout of
// the two `unwrap` calls below mirrors the reference panic locations.
pub fn validate_unanchored(pattern: &str, colorize: bool) {
    if colorize {
        let _ = regex::Regex::new(pattern).unwrap();
    } else {
        let _ = regex::Regex::new(pattern).unwrap();
    }
}
