        if config.ignore_case {
            result.push_str("(?i)");
        }
        if start_anchor {
            result.push('^');
        }
        result.push_str(&body);
        if end_anchor {
            result.push('$');
        }
        result
    };

    if config.colorize {'''
new='''    let top_is_union = matches!(expression, Expr::Union(_));
    let full = if config.verbose {
        let prefix = if config.ignore_case { "(?ix)" } else { "(?x)" };
        format_verbose(&body, prefix, start_anchor, end_anchor)
    } else {
        let mut result = String::new();
        if config.ignore_case {
            result.push_str("(?i)");
        }
        if start_anchor {
            result.push('^');
        }
        result.push_str(&body);
        if end_anchor {
            result.push('$');
        }
        result
    };

    if !start_anchor && !end_anchor {
        let parse_pattern = unanchored_parse_pattern(&full, &body, top_is_union, config);
        crate::regexp::validate_unanchored(&parse_pattern, config.colorize);
    }

    if config.colorize {'''
assert old in s;s=s.replace(old,new)
# Add unanchored_parse_pattern function before lowercase_test_case
s=s.replace('''fn lowercase_test_case''','''fn unanchored_parse_pattern(
    full: &str,
    body: &str,
    top_is_union: bool,
    config: &Config,
) -> String {
    if config.verbose {
        let mut lines: Vec<&str> = full
            .lines()
            .skip(1)
            .map(|line| line.trim_start())
            .collect();
        if top_is_union
            && lines.first().copied() == Some(group_open(config))
            && lines.last().map(|line| line.starts_with(')')).unwrap_or(false)
        {
            lines.remove(0);
            lines.pop();
        }
        lines.join("\\n")
    } else if top_is_union {
        let open = group_open(config);
        if let Some(rest) = body.strip_prefix(open) {
            if let Some(stripped) = rest.strip_suffix(")?") {
                return stripped.to_owned();
            }
            if let Some(stripped) = rest.strip_suffix(')') {
                return stripped.to_owned();
            }
        }
        body.to_owned()
    } else {
        body.to_owned()
    }
}

