rnd=random.Random(3)
for _ in range(300):
 ins=rnd.sample(words,rnd.randint(1,5));flags=rnd.choice([[],[],['-i'],['-r'],['-x'],['-g']])
 a=run('/workspace/executable',flags+ins);b=run('/workspace/target/debug/grex',flags+ins)
 if a!=b:print(flags,ins,'\n ref',a,'\n my',b)
